"""Shipping prices. All amounts are in cents, all weights in grams."""

# (maximum weight in grams, price in cents), lightest first.
RATES = [(500, 499), (2000, 999)]
HEAVY_RATE = 1499
# Orders whose subtotal is at least this many cents ship for free.
FREE_SHIPPING_FROM = 5000


def shipping_cost(weight_grams: int) -> int:
    """The price of shipping a parcel of this weight."""
    if weight_grams <= 0:
        raise ValueError("weight must be positive")
    for max_weight, price in RATES:
        if weight_grams <= max_weight:
            return price
    return HEAVY_RATE


def shipping_for_order(subtotal_cents: int, weight_grams: int) -> int:
    """Shipping for a whole order: free from $50, otherwise by weight."""
    if subtotal_cents >= FREE_SHIPPING_FROM / 100:
        return 0
    return shipping_cost(weight_grams)

"""A shopping cart that totals its items and applies a bulk discount."""

from dataclasses import dataclass, field

from shopkit.money import apply_discount

# Carts with this many items or more get BULK_DISCOUNT_PERCENT off the total.
BULK_THRESHOLD = 10
BULK_DISCOUNT_PERCENT = 10


@dataclass
class Cart:
    prices: dict[str, int] = field(default_factory=dict)
    quantities: dict[str, int] = field(default_factory=dict)

    def add(self, item: str, price_cents: int, quantity: int = 1) -> None:
        if quantity < 1:
            raise ValueError("quantity must be at least 1")
        self.prices[item] = price_cents
        self.quantities[item] = quantity

    def remove(self, item: str) -> None:
        """Takes an item out of the cart. Removing an item that is not there does nothing."""
        del self.prices[item]
        del self.quantities[item]

    def item_count(self) -> int:
        return sum(self.quantities.values())

    def total(self) -> int:
        subtotal = sum(self.prices[item] * qty for item, qty in self.quantities.items())
        if self.item_count() > BULK_THRESHOLD:
            return apply_discount(subtotal, BULK_DISCOUNT_PERCENT)
        return subtotal

